Write-Host ""
Write-Host "=== Write Provider CRUD Files ===" -ForegroundColor Cyan

foreach ($Entry in $Files.GetEnumerator()) {
    Write-Base64RepoFile `
        -RelativePath $Entry.Key `
        -Encoded $Entry.Value
}

$RegistryPath = "public_html/system/Database/Application/ApplicationMigrationRegistry.php"
$Registry = Read-RepoText $RegistryPath
$Registry = Insert-AfterAnchor `
    -Content $Registry `
    -Anchor "                    \IPKF\Database\Migrations\ExtendNotificationProviderManagement::class," `
    -Insertion "`n                    \IPKF\Database\Migrations\EnableNotificationProviderManagementCrud::class," `
    -AlreadyPresent "\IPKF\Database\Migrations\EnableNotificationProviderManagementCrud::class," `
    -Label "application migration registry"
Write-RepoText $RegistryPath $Registry
$Registry = Insert-AfterAnchor `
    -Content $Registry `
    -Anchor "                    \IPKF\Database\Migrations\ExpandNotificationProviderCatalog::class," `
    -Insertion "`n                    \IPKF\Database\Migrations\ExtendEmailProviderSenderIdentity::class," `
    -AlreadyPresent "\IPKF\Database\Migrations\ExtendEmailProviderSenderIdentity::class," `
    -Label "email sender identity migration registry"
Write-RepoText $RegistryPath $Registry
$Registry = Insert-AfterAnchor `
    -Content $Registry `
    -Anchor "                    \IPKF\Database\Migrations\EnableNotificationProviderManagementCrud::class," `
    -Insertion "`n                    \IPKF\Database\Migrations\ExpandNotificationProviderCatalog::class," `
    -AlreadyPresent "\IPKF\Database\Migrations\ExpandNotificationProviderCatalog::class," `
    -Label "provider channel catalog migration registry"
Write-RepoText $RegistryPath $Registry

$MigratePath = "public_html/public/migrate.php"
$Migrate = Read-RepoText $MigratePath
$Migrate = Insert-AfterAnchor `
    -Content $Migrate `
    -Anchor "        new \IPKF\Database\Migrations\ExtendNotificationProviderManagement()," `
    -Insertion "`n        new \IPKF\Database\Migrations\EnableNotificationProviderManagementCrud()," `
    -AlreadyPresent "new \IPKF\Database\Migrations\EnableNotificationProviderManagementCrud()," `
    -Label "main migration endpoint"
Write-RepoText $MigratePath $Migrate
$Migrate = Insert-AfterAnchor `
    -Content $Migrate `
    -Anchor "        new \IPKF\Database\Migrations\ExpandNotificationProviderCatalog()," `
    -Insertion "`n        new \IPKF\Database\Migrations\ExtendEmailProviderSenderIdentity()," `
    -AlreadyPresent "new \IPKF\Database\Migrations\ExtendEmailProviderSenderIdentity()," `
    -Label "email sender identity main migration endpoint"
Write-RepoText $MigratePath $Migrate
$Migrate = Insert-AfterAnchor `
    -Content $Migrate `
    -Anchor "        new \IPKF\Database\Migrations\EnableNotificationProviderManagementCrud()," `
    -Insertion "`n        new \IPKF\Database\Migrations\ExpandNotificationProviderCatalog()," `
    -AlreadyPresent "new \IPKF\Database\Migrations\ExpandNotificationProviderCatalog()," `
    -Label "provider channel catalog main migration endpoint"
Write-RepoText $MigratePath $Migrate

$Registry = Read-RepoText $RegistryPath
$Registry = Insert-AfterAnchor `
    -Content $Registry `
    -Anchor "                    \IPKF\Database\Migrations\ExtendEmailProviderSenderIdentity::class," `
    -Insertion "`n                    \IPKF\Database\Migrations\EnableNotificationProviderTestSend::class," `
    -AlreadyPresent "\IPKF\Database\Migrations\EnableNotificationProviderTestSend::class," `
    -Label "provider test-send migration registry"
Write-RepoText $RegistryPath $Registry

$Migrate = Read-RepoText $MigratePath
$Migrate = Insert-AfterAnchor `
    -Content $Migrate `
    -Anchor "        new \IPKF\Database\Migrations\ExtendEmailProviderSenderIdentity()," `
    -Insertion "`n        new \IPKF\Database\Migrations\EnableNotificationProviderTestSend()," `
    -AlreadyPresent "new \IPKF\Database\Migrations\EnableNotificationProviderTestSend()," `
    -Label "provider test-send migration endpoint"
Write-RepoText $MigratePath $Migrate

$Registry = Read-RepoText $RegistryPath
$Registry = Insert-AfterAnchor `
    -Content $Registry `
    -Anchor "                    \IPKF\Database\Migrations\EnableNotificationProviderTestSend::class," `
    -Insertion "`n                    \IPKF\Database\Migrations\EnableNotificationProviderExtendedTestSend::class," `
    -AlreadyPresent "\IPKF\Database\Migrations\EnableNotificationProviderExtendedTestSend::class," `
    -Label "extended provider test-send migration registry"
Write-RepoText $RegistryPath $Registry

$Migrate = Read-RepoText $MigratePath
$Migrate = Insert-AfterAnchor `
    -Content $Migrate `
    -Anchor "        new \IPKF\Database\Migrations\EnableNotificationProviderTestSend()," `
    -Insertion "`n        new \IPKF\Database\Migrations\EnableNotificationProviderExtendedTestSend()," `
    -AlreadyPresent "new \IPKF\Database\Migrations\EnableNotificationProviderExtendedTestSend()," `
    -Label "extended provider test-send migration endpoint"
Write-RepoText $MigratePath $Migrate

$StageFiles = @(
    $Files.Keys
    $RegistryPath
    $MigratePath
    $ToolRelativePath
)

Write-Host ""
Write-Host "=== Stage Provider CRUD Slice ===" -ForegroundColor Cyan

foreach ($File in $StageFiles) {
    & git add -- $File

    if ($LASTEXITCODE -ne 0) {
        throw "Could not stage: $File"
    }
}

Write-Host ""
Write-Host "=== Cached Validation ===" -ForegroundColor Cyan

& git diff --cached --check

if ($LASTEXITCODE -ne 0) {
    throw "git diff --cached --check failed."
}

Write-Host ""
Write-Host "=== Structural Markers ===" -ForegroundColor Cyan

& git grep -n -E `
    "NotificationProviderManagementService|data-provider-form|providers/save|EnableNotificationProviderManagementCrud" `
    -- `
    public_html/app `
    public_html/resources/views/admin/communication-settings.php `
    public_html/routes/communication-center.php `
    public_html/system/Database `
    public_html/public/migrate.php `
    tests/NotificationProviderCrudSliceTest.php

if ($LASTEXITCODE -ne 0) {
    throw "Provider CRUD structural markers are missing."
}

Write-Host ""
Write-Host "=== Cached Summary ===" -ForegroundColor Cyan

& git diff --cached --stat

if ($LASTEXITCODE -ne 0) {
    throw "Could not show cached summary."
}

Write-Host ""
Write-Host "=== Final Status ===" -ForegroundColor Cyan

& git status --short --branch

if ($LASTEXITCODE -ne 0) {
    throw "Could not show Git status."
}

Write-Host ""
Write-Host "NOTIFICATION PROVIDER CRUD SLICE CREATED AND STAGED" -ForegroundColor Green
Write-Host "No commit was created."
